package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Any invalid value, missing required key or unknown key is a {@link ConfigException} listing every problem,
 * so a typo stops the service at startup instead of letting it run on defaults.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");
    private static final Set<String> KNOWN_KEYS = Set.of(
            "upstream.url",
            "api.token",
            "worker.threads",
            "queue.capacity",
            "retry.max-attempts",
            "request.timeout",
            "metrics.enabled");

    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        ConfigLoader loader = new ConfigLoader(read(file));
        loader.rejectUnknownKeys();
        ServiceConfig config = new ServiceConfig(
                loader.upstream("upstream.url"),
                loader.required("api.token"),
                loader.intValue("worker.threads", DEFAULT_WORKER_THREADS, 1),
                loader.intValue("queue.capacity", DEFAULT_QUEUE_CAPACITY, 1),
                loader.intValue("retry.max-attempts", DEFAULT_RETRY_ATTEMPTS, 0),
                loader.duration("request.timeout", DEFAULT_REQUEST_TIMEOUT),
                loader.booleanValue("metrics.enabled", false));
        if (!loader.problems.isEmpty()) {
            throw new ConfigException(
                    "Invalid configuration in " + file + ":\n  - " + String.join("\n  - ", loader.problems));
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException("Cannot read configuration file " + file + ": " + e, e);
        }
        return properties;
    }

    private void rejectUnknownKeys() {
        for (String key : new TreeSet<>(properties.stringPropertyNames())) {
            if (!KNOWN_KEYS.contains(key)) {
                problems.add(key + " is not a known setting (known: " + new TreeSet<>(KNOWN_KEYS) + ")");
            }
        }
    }

    /** The trimmed value, or null when the key is absent. */
    private String value(String key) {
        String raw = properties.getProperty(key);
        return raw == null ? null : raw.trim();
    }

    private String required(String key) {
        String value = value(key);
        if (value == null || value.isEmpty()) {
            problems.add(key + " is required");
            return null;
        }
        return value;
    }

    private URI upstream(String key) {
        String raw = required(key);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            boolean http = "http".equalsIgnoreCase(uri.getScheme()) || "https".equalsIgnoreCase(uri.getScheme());
            if (http && uri.getHost() != null) {
                return uri;
            }
        } catch (URISyntaxException e) {
            // reported below
        }
        problems.add(key + " must be an http or https URL with a host, was '" + raw + "'");
        return null;
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw);
            if (value >= minimum) {
                return value;
            }
        } catch (NumberFormatException e) {
            // reported below
        }
        problems.add(key + " must be a whole number of at least " + minimum + ", was '" + raw + "'");
        return defaultValue;
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw);
        if (matcher.matches()) {
            try {
                long amount = Long.parseLong(matcher.group(1));
                Duration duration = switch (matcher.group(2)) {
                    case "ms" -> Duration.ofMillis(amount);
                    case "s" -> Duration.ofSeconds(amount);
                    default -> Duration.ofMinutes(amount);
                };
                if (!duration.isZero()) {
                    return duration;
                }
            } catch (ArithmeticException | NumberFormatException e) {
                // reported below
            }
        }
        problems.add(key + " must be a positive whole number followed by ms, s or m (e.g. 30s), was '" + raw + "'");
        return defaultValue;
    }

    private boolean booleanValue(String key, boolean defaultValue) {
        String raw = value(key);
        if (raw == null) {
            return defaultValue;
        }
        if (raw.equalsIgnoreCase("true") || raw.equalsIgnoreCase("false")) {
            return Boolean.parseBoolean(raw);
        }
        problems.add(key + " must be true or false, was '" + raw + "'");
        return defaultValue;
    }
}

